}
function save_infrastructure_settings(array $in): void {
    $p=infrastructure_settings();foreach(['bridge','gateway','web_ipv4','web_ipv6','mail_host'] as $k)$p[$k]=trim((string)($in[$k]??$p[$k]));$p['mac_required']=isset($in['mac_required'])?1:0;
