    if(one("SELECT meta_key FROM shop_meta WHERE meta_key='infrastructure_settings'"))query("UPDATE shop_meta SET meta_value=? WHERE meta_key='infrastructure_settings'",[json_encode($p)]);else query("INSERT INTO shop_meta (meta_key,meta_value) VALUES ('infrastructure_settings',?)",[json_encode($p)]);
}
function save_network_address(int $id,array $in): int {
    $old=$id?one('SELECT * FROM shop_network_addresses WHERE id=?',[$id]):null;if($id && !$old)throw new RuntimeException('IP-Eintrag nicht gefunden.');$s=infrastructure_settings();$ip=trim((string)($in['address']??''));$mac=strtoupper(trim((string)($in['mac']??'')));$gw=trim((string)($in['gateway']??$s['gateway']));$bridge=trim((string)($in['bridge']??$s['bridge']));$node=trim((string)($in['node']??''));$prefix=module_quantity($in['prefix_len']??32);$state=(string)($in['state']??'review');$note=trim((string)($in['notes']??''));
    if(!filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4) || !filter_var($gw,FILTER_VALIDATE_IP,FILTER_FLAG_IPV4) || $prefix<1 || $prefix>32 || !preg_match('/^[\w.-]{1,40}$/D',$bridge) || !preg_match('/^[\w.-]{0,80}$/D',$node) || ($mac && !preg_match('/^(?:[0-9A-F]{2}:){5}[0-9A-F]{2}$/D',$mac)) || !in_array($state,['review','available','reserved','assigned','blocked','build_ready','building'],true) || mb_strlen($note)>1000)throw new RuntimeException('Bitte eine gültige IPv4-/MAC-Zuordnung und Netzwerkvorgaben eintragen.');
    if($state==='available' && $mac && one("SELECT id FROM shop_network_addresses WHERE UPPER(mac)=? AND id<>? AND state IN ('available','reserved','assigned')",[$mac,$id]))throw new RuntimeException('Diese MAC ist bereits für eine andere freigegebene oder vergebene Adresse reserviert.');
    if($state==='available' && $s['mac_required'] && !$mac)throw new RuntimeException('Für die Freigabe bitte zuerst die zugehörige OVH-MAC-Adresse eintragen oder importieren.');
    if($old && ($old['order_id'] || $old['service_id'] || in_array($old['state'],['build_ready','building'],true))){if($state!==$old['state'] || $ip!==$old['address'] || $mac!==($old['mac']??'') || $gw!==$old['gateway'] || $bridge!==$old['bridge'] || $node!==$old['node'] || $prefix!==(int)$old['prefix_len'])throw new RuntimeException('Ein vergebener Netzwerkeintrag bleibt fest dem Kundenserver zugeordnet.');}
    elseif(in_array($state,['assigned','reserved','build_ready','building'],true))throw new RuntimeException('Reservierung und Zuteilung erfolgen ausschließlich über die Bestellung.');
    if(one('SELECT id FROM shop_network_addresses WHERE address=? AND id<>?',[$ip,$id]))throw new RuntimeException('Diese IP-Adresse ist bereits im Pool.');
    $args=[$ip,$prefix,$mac?:null,$gw,$bridge,$node,$state,$note];if($id)query('UPDATE shop_network_addresses SET address=?,prefix_len=?,mac=?,gateway=?,bridge=?,node=?,state=?,notes=? WHERE id=?',[...$args,$id]);else{query("INSERT INTO shop_network_addresses (address,prefix_len,mac,gateway,bridge,node,state,notes) VALUES (?,?,?,?,?,?,?,?)",$args);$id=(int)db()->lastInsertId();}audit_event('network.address.saved',(string)$id);return $id;
}
function ovh_network_inventory(): array {
    $api=new OvhProvider();$blocks=$api->call('GET','/ip');if(!is_array($blocks))throw new ProviderFailure('ovh');$addresses=[];
    foreach($blocks as $cidr){if(!is_string($cidr) || !preg_match('/^(\d+\.\d+\.\d+\.\d+)\/(\d+)$/D',$cidr,$m) || !filter_var($m[1],FILTER_VALIDATE_IP,FILTER_FLAG_IPV4))continue;$prefix=(int)$m[2];if($prefix<20 || $prefix>32)continue;$count=2**(32-$prefix);$start=(int)sprintf('%u',ip2long($m[1]));for($i=0;$i<$count && count($addresses)<4096;$i++){$ip=long2ip($start+$i);$addresses[$ip]=['address'=>$ip,'provider_ref'=>$cidr,'mac'=>null];}}
    $macError='';try{foreach($api->call('GET','/dedicated/server') as $server){$path='/dedicated/server/'.rawurlencode($server).'/virtualMac';foreach($api->call('GET',$path) as $mac){foreach($api->call('GET',$path.'/'.rawurlencode($mac).'/virtualAddress') as $ip){if(isset($addresses[$ip]))$addresses[$ip]['mac']=strtoupper($mac);}}}}catch(ProviderFailure $e){$macError='IP-Liste importiert. Für virtuelle MACs benötigt der OVH-Zugang zusätzlich GET /dedicated/server/*/virtualMac*.';}
    $settings=infrastructure_settings();$created=0;$updated=0;$reviewed=0;
    foreach($addresses as $ip=>$v){
        $row=one('SELECT * FROM shop_network_addresses WHERE address=?',[$ip]);
        if(!$row){query("INSERT INTO shop_network_addresses (address,mac,gateway,bridge,provider_ref,state,notes) VALUES (?,?,?,?,?,'review','Aus OVH importiert. Vor Freigabe auf bestehende Nutzung prüfen.')",[$ip,$v['mac'],$settings['gateway'],$settings['bridge'],$v['provider_ref']]);$created++;continue;}
        // Existing customers and a running builder retain their fixed network identity.
        if($row['order_id'] || $row['service_id'] || in_array($row['state'],['reserved','assigned','build_ready','building'],true))continue;
        $mac=$macError?($row['mac']??null):$v['mac'];$changed=strtoupper($row['mac']??'')!==strtoupper($mac??'');
        $state=$row['state'];if($state==='available' && $changed){$state='review';$reviewed++;}
        if($changed || $row['provider_ref']!==$v['provider_ref']){query('UPDATE shop_network_addresses SET mac=?,provider_ref=?,state=? WHERE id=?',[$mac,$v['provider_ref'],$state,$row['id']]);$updated++;}
    }
    foreach(all("SELECT id,address FROM shop_network_addresses WHERE provider_ref<>'' AND state='available' AND order_id IS NULL AND service_id IS NULL") as $row)if(!isset($addresses[$row['address']])){query("UPDATE shop_network_addresses SET state='review' WHERE id=?",[$row['id']]);$reviewed++;}
    if($reviewed)$macError.=($macError?' ':'').$reviewed.' geänderte oder nicht mehr gelistete Adressen benötigen eine erneute Prüfung.';
    audit_event('network.ovh.imported');return ['created'=>$created,'updated'=>$updated,'notice'=>$macError];
}
function reserve_network_address(array $order,string $node): array {
    if($old=one('SELECT * FROM shop_network_addresses WHERE order_id=?',[$order['id']])){if($old['node'] && $old['node']!==$node)throw new RuntimeException('Die reservierte IP gehört zu einem anderen Node.');return $old;}
    db()->beginTransaction();try{$lock=db()->getAttribute(PDO::ATTR_DRIVER_NAME)==='mysql'?' FOR UPDATE':'';$s=infrastructure_settings();$row=one("SELECT * FROM shop_network_addresses WHERE state='available' AND order_id IS NULL AND service_id IS NULL AND (node='' OR node=?)".($s['mac_required']?" AND mac IS NOT NULL AND mac<>''":'')." ORDER BY id LIMIT 1".$lock,[$node]);if(!$row)throw new RuntimeException('Keine freigegebene IP-/MAC-Zuordnung für diesen Node verfügbar. Bitte den Adresspool ergänzen.');query("UPDATE shop_network_addresses SET state='reserved',order_id=?,node=? WHERE id=? AND state='available'",[$order['id'],$node,$row['id']]);db()->commit();return one('SELECT * FROM shop_network_addresses WHERE id=?',[$row['id']]);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
}
function server_template_choices(int $product,bool $active=true): array {return all('SELECT t.* FROM shop_server_templates t JOIN shop_server_template_bindings b ON b.template_id=t.id WHERE b.product_id=?'.($active?' AND t.active=1':'').' ORDER BY t.sort_order,t.id',[$product]);}
function save_server_template(int $id,array $in): int {
