    if(!$name || mb_strlen($name)>120 || mb_strlen($desc)>2000 || !preg_match('/^[\w.-]{1,80}$/D',$node) || !preg_match('/^[\w.-]{1,80}$/D',$storage) || ($archive && !preg_match('/^[\w.-]+:(?:vztmpl|backup)\/[\w.\/-]+$/D',$archive)) || str_contains($archive,'..') || ($source && (!filter_var($source,FILTER_VALIDATE_URL) || !str_starts_with($source,'https://'))))throw new RuntimeException('Bitte Vorlagenname, Node, Storage und ein Proxmox-Template- oder Backup-Volume eintragen.');
