    if($settings['disk_gb']<1 || $settings['disk_gb']>65536 || $settings['min_memory_mb']<128 || $settings['min_memory_mb']>1048576 || $settings['min_cores']<1 || $settings['min_cores']>128 || !filter_var($settings['nameserver'],FILTER_VALIDATE_IP))throw new RuntimeException('Bitte gültige Mindestressourcen und einen DNS-Resolver eintragen.');
