    $settings['build_script']=trim((string)($in['build_script']??$prior['build_script']??''));$settings['build_os']=trim((string)($in['build_os']??$prior['build_os']??''));$settings['build_version']=trim((string)($in['build_version']??$prior['build_version']??''));$settings['build_profile']=trim((string)($in['build_profile']??$prior['build_profile']??''));
    if(($settings['build_script'] && !in_array($settings['build_script'],template_build_catalog(),true)) || !in_array($settings['build_os'],['','debian','ubuntu','alpine','centos','fedora','gentoo','archlinux'],true) || !preg_match('/^[a-zA-Z0-9_.-]{0,30}$/D',$settings['build_version']) || !in_array($settings['build_profile'],['','ubuntu-webserver'],true))throw new RuntimeException('Bitte gültige Bauoptionen für die LXC-Vorlage auswählen.');
    if($active){if(!$archive)throw new RuntimeException('Vor der Freigabe wird eine vorbereitete Proxmox-Vorlage benötigt.');$api=new ProxmoxProvider();$found=false;$sourceStorage=explode(':',$archive,2)[0];foreach($api->call('GET','/nodes/'.rawurlencode($node).'/storage/'.rawurlencode($sourceStorage).'/content') as $v)if(($v['volid']??'')===$archive)$found=true;if(!$found)throw new RuntimeException('Das gewählte Volume wurde auf diesem Node nicht gefunden.');}
    $args=[$name,$desc,$node,$archive,$storage,$source,json_encode($settings),$active?1:0];if($id){if(!one('SELECT id FROM shop_server_templates WHERE id=?',[$id]))throw new RuntimeException('Vorlage nicht gefunden.');query('UPDATE shop_server_templates SET name=?,description=?,node=?,archive=?,storage=?,source_url=?,settings=?,active=? WHERE id=?',[...$args,$id]);}else{query('INSERT INTO shop_server_templates (name,description,node,archive,storage,source_url,settings,active) VALUES (?,?,?,?,?,?,?,?)',$args);$id=(int)db()->lastInsertId();}audit_event('server.template.saved',(string)$id);return $id;
}
function selected_server_template(array $p,mixed $choice=0): array {
    $a=checkout_automation($p);if(($a['settings']['virtualization']??'qemu')!=='lxc' || isset($p['_quote_id']))return $p;$templates=server_template_choices((int)$p['id']);$id=module_quantity($choice?:($templates[0]['id']??0));$selected=null;foreach($templates as $t)if((int)$t['id']===$id)$selected=$t;if(!$selected)throw new RuntimeException('Für dieses VPS-Paket ist noch keine Betriebssystem-Vorlage freigegeben.');$s=json_decode($selected['settings'],true);$profile=$a['settings'];if((int)$profile['memory_mb']<(int)$s['min_memory_mb'] || (int)$profile['cores']<(int)$s['min_cores'])throw new RuntimeException('Die gewählte Vorlage benötigt mindestens '.$s['min_cores'].' vCPU und '.$s['min_memory_mb'].' MB RAM.');$profile['server_template']=$selected;$p['_automation']=array_replace($a,['settings'=>$profile]);$p['_server_template_id']=$id;if(isset($p['_base_product'])){$b=$p['_base_product'];$b['_automation']=checkout_automation($b);$b['_automation']['settings']['server_template']=$selected;$p['_base_product']=$b;}return $p;
}
function save_server_template_bindings(int $product,array $in): void {
    if(!isset($in['server_templates_present']))return;$ids=$in['server_templates']??[];if(!is_array($ids))throw new RuntimeException('Ungültige Vorlagenauswahl.');$p=one('SELECT category FROM shop_products WHERE id=?',[$product]);if($p['category']!=='server')$ids=[];foreach($ids as $id)if(!one('SELECT id FROM shop_server_templates WHERE id=?',[(int)$id]))throw new RuntimeException('Vorlage nicht gefunden.');query('DELETE FROM shop_server_template_bindings WHERE product_id=?',[$product]);foreach(array_unique($ids) as $id)query('INSERT INTO shop_server_template_bindings (product_id,template_id) VALUES (?,?)',[$product,(int)$id]);
